/* Combah single-page frontend. Server verifies all permissions and calculates prices. */
const S={pub:null,me:null,csrf:null,orders:[],shipRequests:[],packages:[],shipments:[],notifications:[],overview:{},customers:[],payments:[],settings:{},audit:[],page:'overview',search:'',statusFilter:'',modal:null,quote:null,menu:false,loaded:false};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const cash=c=>new Intl.NumberFormat('en-GH',{style:'currency',currency:'GHS',maximumFractionDigits:2}).format((Number(c)||0)/100);
const date=v=>v?new Date(v).toLocaleDateString('en-GH',{day:'2-digit',month:'short',year:'numeric'}):'—';
const human=s=>String(s||'').replaceAll('_',' ').toLowerCase().replace(/\b\w/g,s=>s.toUpperCase());
const dateTime=v=>v?new Date(v).toLocaleString('en-GH',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const clip=s=>navigator.clipboard?.writeText(s).then(()=>toast('Copied to clipboard')).catch(()=>toast('Copy not available'));
const iconPaths={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',up:'<path d="m7 14 5-5 5 5"/>',down:'<path d="m7 10 5 5 5-5"/>',box:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 0v10l9 4 9-4V7m-9 4v10"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-4 4-4 14 0 18m0-18c4 4 4 14 0 18"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',truck:'<path d="M3 5h12v12H3zM15 9h4l3 4v4h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',package:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 0v10l9 4 9-4V7m-9 4v10m-5-6 9 4 9-4"/>',users:'<path d="M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m19 0v-2a4 4 0 0 0-3-3.87M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM17 2a4 4 0 0 1 0 8"/>',credit:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 10h20"/>',chart:'<path d="M4 19V9m6 10V5m6 14v-7m4 7H2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 13.5V10.5m-14 3v-3M10.5 5h3m-3 14h3m-7-3-2 2m14-14-2 2M6 6 4 4m14 14 2 2"/>',file:'<path d="M7 3h8l5 5v13H7zM15 3v5h5M10 13h7m-7 4h7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 13h4"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',logout:'<path d="M10 17l5-5-5-5m5 5H3m8-9h10v18H11"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 4h.01"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M4 6h.01M4 12h.01M4 18h.01"/>',plus:'<path d="M12 4v16M4 12h16"/>',edit:'<path d="m4 20 5-.8L20 8l-4-4L5 15l-1 5Zm10-14 4 4"/>',eye:'<path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 9a8 8 0 0 1 14-2m0 8a8 8 0 0 1-14 2"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
const ico=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.box}</svg>`;
const brand=()=>`<a class="brand" href="/" data-nav="/" aria-label="Combah home"><span class="brand-mark">C</span><span class="brand-copy"><strong>combah.</strong><small>Procurement & Logistics</small></span></a>`;
const badge=s=>{let t=String(s||'').toUpperCase();let cls=/COMPLETE|VERIFIED|READY_FOR_COLLECTION|RECEIVED|ACTIVE/.test(t)?'green':/AWAITING|REVIEW|PENDING|OFFICER/.test(t)?'orange':/REJECTED|CANCELLED|DAMAGED/.test(t)?'red':/TRANSIT|PROCUREMENT|SUPPLIER|CLEARANCE|ARRIVED|DISPATCHED/.test(t)?'blue':'';return `<span class="badge ${cls}"><i class="bullet"></i>${esc(human(s))}</span>`};
const f=(label,name,type='text',value='',placeholder='',required=false)=>`<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><input id="f-${attr(name)}" name="${attr(name)}" type="${type}" value="${attr(value)}" placeholder="${attr(placeholder)}" ${required?'required':''}/></div>`;
const sel=(label,name,opts,value='',required=true)=>`<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><select id="f-${attr(name)}" name="${attr(name)}" ${required?'required':''}><option value="">Select ${esc(label.toLowerCase())}</option>${opts.map(v=>{const [val,display]=Array.isArray(v)?v:[v,v];return `<option value="${attr(val)}" ${String(val)===String(value)?'selected':''}>${esc(display)}</option>`}).join('')}</select></div>`;
const textarea=(label,name,value='',placeholder='')=>`<div class="field"><label>${esc(label)}</label><textarea name="${attr(name)}" placeholder="${attr(placeholder)}">${esc(value)}</textarea></div>`;
const primary=(label,action='',cls='primary')=>`<button class="btn ${cls}" ${action?`data-action="${action}"`:''}>${label}</button>`;
const regs=()=>S.pub?.regions||[];
const api=async(path,{method='GET',body=null}={})=>{
 const res=await fetch(path,{method,credentials:'same-origin',headers:{...(body!==null?{'Content-Type':'application/json'}:{}),...(S.csrf?{'X-CSRF-Token':S.csrf}:{})},...(body!==null?{body:JSON.stringify(body)}:{})});
 let json;try{json=await res.json()}catch{json={detail:'Connection failed'}}
 if(!res.ok){if(res.status===401&&S.me){S.me=null;navigate('/login');}throw Error(typeof json.detail==='string'?json.detail:'Request could not be completed.')}
 return json;
};
const toast=(msg,bad=false)=>{const el=document.createElement('div');el.className='toast'+(bad?' bad':'');el.textContent=msg;$('#toast-root').append(el);setTimeout(()=>el.remove(),4200)};
const route=()=>window.location.pathname;
function navigate(path){history.pushState({},'',path);S.search='';S.statusFilter='';S.modal=null;S.menu=false;window.scrollTo(0,0);loadRoute()}
window.addEventListener('popstate',()=>loadRoute());
async function bootstrap(){try{S.pub=await api('/api/public');try{const session=await api('/api/me');S.me=session.user;S.csrf=session.csrf}catch{}await loadRoute()}catch(e){$('#app').innerHTML=`<div class="boot"><h2>We couldn't start Combah.</h2><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">Retry</button></div>`}}
async function loadRoute(){const path=route();if(path==='/login'||path==='/register'){S.me? navigate('/app'):renderAuth(path==='/register');return}if(path.startsWith('/app')){if(!S.me){navigate('/login');return}S.page=(path.split('/')[2]||'overview');await reload();return}renderHome()}
async function reload(){try{const role=S.me.role;let paths=['/api/notifications','/api/ship-requests'];if(role==='customer')paths.push('/api/orders','/api/packages','/api/shipments');if(role==='warehouse')paths.push('/api/packages');if(role==='admin')paths.push('/api/admin/overview','/api/orders','/api/packages','/api/shipments','/api/admin/customers','/api/admin/payments','/api/admin/audit','/api/admin/settings');const data=await Promise.all(paths.map(p=>api(p)));let i=0;S.notifications=data[i++];S.shipRequests=data[i++];if(role==='admin')S.overview=data[i++];if(role==='customer'||role==='admin')S.orders=data[i++];if(role==='customer'||role==='warehouse'||role==='admin')S.packages=data[i++];if(role==='customer'||role==='admin')S.shipments=data[i++];if(role==='admin'){S.customers=data[i++];S.payments=data[i++];S.audit=data[i++];S.settings=data[i++]};renderApp()}catch(e){toast(e.message,true);renderApp()}}
function renderHome(){document.title='Combah | Buy in China. Receive in Ghana.';const contact=S.pub.contact||{};$('#app').innerHTML=`
<section class="hero" id="home"><div class="container"><header class="topbar">${brand()}<nav class="links"><a href="#services">Our services</a><a href="#how">How it works</a><a href="#coverage">Coverage</a><a href="#estimate">Pricing</a></nav><div class="row-flex"><a class="btn outline small" href="/login" data-nav="/login">Log in</a><a class="btn primary small" href="/register" data-nav="/register">Get started ${ico('arrow','sm')}</a></div></header>
<div class="hero-shell"><div><div class="eyebrow">Your China-to-Ghana logistics partner</div><h1>Source globally.<br><em>Deliver locally.</em></h1><p class="lead">From finding your next product in China to receiving it in Ghana, Combah brings procurement, shipping, and tracking together in one simple platform.</p><div class="hero-actions"><a href="/register" data-nav="/register" class="btn primary">Start shipping with Combah ${ico('arrow','sm')}</a><a href="#how" class="btn outline">See how it works ${ico('arrow','sm')}</a></div><div class="hero-points"><span>${ico('check','sm')} Your own China shipping reference</span><span>${ico('check','sm')} End-to-end visibility</span></div></div>
<div class="visual" aria-label="Illustration of the China to Ghana delivery route"><div class="visual-pane"><div class="orb"></div><div class="visual-top"><span><i class="dot"></i>COMBAH GLOBAL ROUTE</span><span>CN → GH</span></div><svg class="visual-curve" viewBox="0 0 550 410" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="routegrad" x1="0" x2="1"><stop stop-color="#edd19a"/><stop offset="1" stop-color="#4fc39e"/></linearGradient></defs><path d="M 100 153 C 205 45, 307 345, 435 218" stroke="url(#routegrad)" stroke-width="2.5" stroke-dasharray="8 8" fill="none"/><path d="m423 220 12-3-6 12" stroke="#6ad4b3" stroke-width="2" fill="none"/><circle cx="100" cy="153" r="15" fill="#e8d3a1" opacity=".1"/><circle cx="435" cy="218" r="14" fill="#79e5c2" opacity=".1"/></svg><div class="map-point a"></div><div class="map-point b"></div><div class="map-label china">CHINA<span>Source & warehouse</span></div><div class="map-label ghana">GHANA<span>Delivered to you</span></div></div><div class="floating tracking"><small>ORDER JOURNEY</small><b style="margin-top:5px">Always in the loop</b><div class="steps"><i class="done"></i><i class="done"></i><i class="done"></i><i></i><i></i></div></div><div class="floating package"><div class="float-icon">${ico('box','lg')}</div><div><b>One shipping reference</b><small>Every package, connected to you</small></div></div></div></div></div></section>
<div class="stats-strip"><div class="container stats-grid"><div class="stat-mini">${ico('globe')}<div><strong>China to Ghana</strong><small>Cross-border sourcing</small></div></div><div class="stat-mini">${ico('location')}<div><strong>16 regions</strong><small>Platform designed for Ghana</small></div></div><div class="stat-mini">${ico('package')}<div><strong>Package-level records</strong><small>Warehouse-to-door visibility</small></div></div><div class="stat-mini">${ico('shield')}<div><strong>One account</strong><small>Procure, ship and track</small></div></div></div></div>
<section class="section" id="services"><div class="container"><div class="section-head"><div class="eyebrow">Made for the way you import</div><h2>Two services.<br>One seamless experience.</h2><p>Whether you need help purchasing in China or only need a reliable shipping partner, we've designed a path for you.</p></div><div class="services"><article class="service-card"><div class="service-icon">${ico('credit','lg')}</div><span class="eyebrow">01 · Sourcing & procurement</span><h3>Buy for Me</h3><p>Found something you want? Share a product link, review a transparent quotation, and let Combah manage the procurement journey.</p><ul><li>${ico('check','sm')} Submit a Chinese supplier or marketplace link</li><li>${ico('check','sm')} See product cost and configured service fees</li><li>${ico('check','sm')} Follow your request from purchase to delivery</li></ul><a href="/register" data-nav="/register" class="inline-link">Create a procurement request →</a></article><article class="service-card"><div class="service-icon">${ico('box','lg')}</div><span class="eyebrow">02 · Cross-border freight</span><h3>Ship for Me</h3><p>Already purchased your products? Use your Combah customer reference for warehouse matching and follow each parcel as it moves to Ghana.</p><ul><li>${ico('check','sm')} Get a permanent Combah Customer ID</li><li>${ico('check','sm')} Have your packages recorded on China arrival</li><li>${ico('check','sm')} Track shipment and Ghana pickup/delivery</li></ul><a href="/register" data-nav="/register" class="inline-link">Get your shipping reference →</a></article></div></div></section>
<section class="section dark-section" id="how"><div class="container split"><div><div class="eyebrow light">One connected journey</div><h2>From a supplier in China to your hands in Ghana.</h2><p class="muted">No scattered messages or guesswork. With a single account, you can see how your procurement and packages are progressing through Combah's workflow.</p><div class="number-steps"><div class="number-step"><span class="num">01</span><div><strong>Create your Combah account</strong><small>Receive your unique customer ID for China warehouse matching.</small></div></div><div class="number-step"><span class="num">02</span><div><strong>Buy with us or ship your own goods</strong><small>Request procurement, or use your personal customer reference for items you buy yourself.</small></div></div><div class="number-step"><span class="num">03</span><div><strong>Track every milestone</strong><small>Follow warehouse receipt, transit, Ghana clearance and regional dispatch.</small></div></div></div></div><div class="quote-panel" id="estimate"><span class="eyebrow">Transparent by design</span><h3>Estimate your procurement cost</h3><p>Preview a provisional quotation in Ghana cedis.</p><div class="quote-grid"><div class="field"><label>Product unit price (GHS)</label><input type="number" id="quote-price" min="0.01" step="0.01" value="250"/></div><div class="field"><label>Quantity</label><input type="number" id="quote-qty" min="1" value="2"/></div><div class="field"><label>Est. weight (kg, optional)</label><input type="number" id="quote-weight" min="0.1" step="0.1" placeholder="Not sure yet"/></div><div class="field"><label>Service</label><input value="Buy for Me" disabled/></div></div><div id="public-quote-result"><div class="loading">Calculating…</div></div><a href="/register" data-nav="/register" class="btn primary" style="width:100%;margin-top:14px">Continue to request ${ico('arrow','sm')}</a></div></div></section>
<section class="section coverage-section" id="coverage"><div class="container coverage-layout"><div style="max-width:360px"><div class="eyebrow">Ghana-wide by design</div><h2>Built for all 16 regions.</h2><p style="color:#738b8b;font-size:14px">Starting from Tamale, Combah is designed to serve customers across Ghana as pickup and delivery partnerships expand. Actual service availability is confirmed during fulfillment.</p></div><div class="regions">${regs().map(r=>`<span class="region-pill">${esc(r)}</span>`).join('')}</div></div></section>
<section class="section"><div class="container split"><div><div class="eyebrow">Confidence in every order</div><h2>Clarity from start to finish.</h2><p style="color:#7a8e8e">From confirmed payment to warehouse scans and shipment milestones, your records stay together. Combah gives you visibility at each stage and an easy way to contact the team when you need help.</p><a href="/register" data-nav="/register" class="btn primary">Set up your free account ${ico('arrow','sm')}</a></div><div class="panel" style="padding:30px;margin:0"><div class="panel-title"><h3>Example shipment timeline</h3>${badge('IN_TRANSIT')}</div><div class="timeline">${[['Account created','Your unique customer ID is assigned'],['Received in China','Warehouse staff record the package'],['Ready for shipping','Package assigned to the freight workflow'],['In transit','Shipment moving toward Ghana']].map(([a,b])=>`<div class="timeline-event"><div class="timeline-pin"></div><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div><small style="color:#91a1a1">Illustrative tracking journey; not a live shipment.</small></div></div></section>

<section class="section" id="faq"><div class="container" style="max-width:900px"><div class="section-head"><div class="eyebrow">Useful answers</div><h2>Frequently asked questions.</h2><p>What to know before your first import.</p></div><div class="faq-list"><details><summary>Can I buy goods myself and only use Combah for shipping?</summary><p>Yes. With Ship for Me, goods bought independently can be sent to Combah's verified China warehouse address using your permanent Customer ID, which allows the warehouse team to match the parcel to you.</p></details><details><summary>How is my procurement cost calculated?</summary><p>Our estimate combines the product subtotal, configured procurement fee, handling charge and estimated freight when weight is available. Final shipping costs can change after warehouse measurements and applicable clearance charges.</p></details><details><summary>How do payments work?</summary><p>At this stage, customers must use payment instructions verified directly with Combah. A payment reference submitted through the dashboard is manually checked before procurement starts. The website does not currently process online payments.</p></details><details><summary>Do you deliver to all regions in Ghana?</summary><p>The system is designed for all 16 regions with Tamale as the initial operations hub. Actual pickup and delivery services depend on operational availability and will be confirmed for each shipment.</p></details><details><summary>When will I receive my China warehouse address?</summary><p>Every customer receives a permanent Customer ID immediately. The physical China warehouse address will be shown once Combah has officially verified and configured it. Do not ship items to an unconfirmed address.</p></details></div></div></section>
<section class="cta-strip"><div class="container cta-layout"><div><span class="eyebrow">Your products. Your way.</span><h2>Ready to bring it home?</h2><p style="margin:10px 0 0;color:#476764">Your China-to-Ghana journey starts with one account.</p></div><a href="/register" data-nav="/register" class="btn primary">Get started today ${ico('arrow','sm')}</a></div></section>
<footer class="footer"><div class="container"><div class="footer-top"><div>${brand()}<p style="max-width:270px;margin-top:17px">Buy in China. Pick up or receive anywhere in Ghana, as regional services become available.</p></div><div><h4>Explore</h4><a href="#services">Our services</a><a href="#how">How it works</a><a href="#coverage">Coverage</a><a href="#faq">FAQs</a></div><div><h4>Account</h4><a href="/register" data-nav="/register">Create account</a><a href="/login" data-nav="/login">Customer sign in</a><a href="/login" data-nav="/login">Staff portal</a></div><div><h4>Reach us</h4><p>${esc(contact.ghana_hub||'Tamale, Northern Region, Ghana')}<br>${esc(contact.support_email||'Contact details to be confirmed')}<br>${esc(contact.support_phone||'')}</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Combah Procurement & Logistics. All rights reserved.</span><span>Procurement · Warehouse · Freight · Ghana delivery</span></div></div></footer>`;refreshPublicQuote();}
async function refreshPublicQuote(){const unit=parseFloat($('#quote-price')?.value),qty=+$('#quote-qty')?.value,weight=parseFloat($('#quote-weight')?.value);if(!(unit>0&&qty>0))return;try{const q=await api(`/api/quote?unit_price=${encodeURIComponent(unit)}&quantity=${encodeURIComponent(qty)}${weight>0?`&weight=${encodeURIComponent(weight)}`:''}`);let box=$('#public-quote-result');if(!box)return;box.innerHTML=`<div class="price-row"><span>Product subtotal</span><strong>${cash(q.subtotal_cents)}</strong></div><div class="price-row"><span>Procurement service</span><strong>${cash(q.procurement_fee_cents)}</strong></div><div class="price-row"><span>Handling</span><strong>${cash(q.handling_fee_cents)}</strong></div><div class="price-row"><span>Est. international freight</span><strong>${weight>0?cash(q.freight_estimate_cents):'Pending weight'}</strong></div><div class="price-row total"><span>Provisional total</span><strong>${cash(q.total_cents)}</strong></div><p class="disclaimer">${esc(q.note)}</p>`}catch(e){toast(e.message,true)}}
function renderAuth(register){document.title=(register?'Create account':'Sign in')+' | Combah';$('#app').innerHTML=`<div class="auth-page"><aside class="auth-aside"><div class="auth-side-content">${brand()}</div><div class="auth-side-content"><span class="eyebrow light">COMBAH CUSTOMER EXPERIENCE</span><h2>Closer to the goods you need.</h2><p>Manage your sourcing, China warehouse deliveries and Ghana shipments with one connected account.</p><div class="hero-points" style="color:#b2c8c8;margin-top:30px"><span>${ico('check','sm')} Account-level tracking</span><span>${ico('check','sm')} Secure role-based access</span></div></div><div class="auth-side-content" style="font-size:11px;color:#86a8ae">CHINA → GHANA · COMBAH</div><div class="auth-orbit"></div></aside><main class="auth-main"><div class="auth-card"><a href="/" data-nav="/" class="inline-link" style="font-size:12px">← Back to website</a><div style="margin-top:30px"><span class="eyebrow">${register?'Get started':'Welcome back'}</span><h2>${register?'Create your account':'Sign in to Combah'}</h2><p class="sub">${register?'Get your unique customer ID and stay on top of every package.':'Access your orders, packages and shipment updates.'}</p></div><form id="auth-form" data-form="${register?'register':'login'}">${register?`${f('Full name','full_name','text','','Your full name',true)}<div class="form-row">${f('Email address','email','email','','you@example.com',true)}${f('Phone number','phone','tel','','+233 …')}</div><div class="form-row">${sel('Region','region',regs(),'',true)}${f('District / city','district','text','','e.g. Tamale')}</div>`:`${f('Email address','email','email','','you@example.com',true)}`}${f('Password','password','password','',register?'At least 10 characters, letters and numbers':'Enter your password',true)}<div id="auth-error"></div><button class="btn primary" type="submit" style="width:100%;margin-top:10px">${register?'Create account':'Sign in'} ${ico('arrow','sm')}</button></form><div class="auth-foot">${register?'Already have an account?':'New to Combah?'} <a class="inline-link" href="${register?'/login':'/register'}" data-nav="${register?'/login':'/register'}">${register?'Sign in':'Create an account'}</a></div>${S.pub.demo?`<div class="auth-demo"><p><b>Preview mode</b> · Choose an account to explore the platform.</p><div class="demo-options"><button data-demo="customer">Customer</button><button data-demo="warehouse">China warehouse</button><button data-demo="admin">Admin</button></div></div>`:''}</div></main></div>`}
const sections={customer:[['overview','Overview','home'],['new-order','Buy for Me','plus'],['ship-for-me','Ship for Me','truck'],['ship-requests','My shipping requests','list'],['orders','My orders','list'],['packages','My packages','package'],['shipments','Shipments','truck'],['notifications','Notifications','bell'],['profile','My profile','users']],warehouse:[['overview','Overview','home'],['receive','Receive package','plus'],['ship-requests','Expected arrivals','list'],['packages','Warehouse inventory','package'],['lookup','Find customer','search'],['profile','My profile','users']],admin:[['overview','Overview','home'],['orders','Procurement','list'],['ship-requests','Ship for Me requests','truck'],['payments','Payments','credit'],['packages','Warehouse packages','box'],['shipments','Shipments','truck'],['customers','Customers & staff','users'],['pricing','Pricing & settings','settings'],['activity','Activity log','clock'],['notifications','Notifications','bell']]};
