 if(type==='create-shipment'){let ids=d.getAll('package_id').map(Number);if(!ids.length)throw Error('Select at least one package.');const b={package_ids:ids,carrier:val('carrier'),tracking_number:val('tracking_number'),destination_region:val('destination_region'),eta:val('eta'),notes:val('notes')};const sh=await api('/api/shipments',{method:'POST',body:b});S.modal=null;await reload();toast(sh.shipment_ref+' created');return}
 if(type==='shipment-status'){await api('/api/shipments/'+val('id'),{method:'PATCH',body:{status:val('status'),carrier:val('carrier'),tracking_number:val('tracking_number'),eta:val('eta'),notes:val('notes')}});S.modal=null;await reload();toast('Shipment tracking updated');return}
 if(type==='settings'){const keys=['procurement_percent','handling_fee_ghs','estimated_freight_per_kg_ghs','ship_for_me_handling_ghs','support_email','support_phone','china_warehouse_address','ghana_hub','notice'];const b={};keys.forEach(k=>b[k]=val(k));await api('/api/admin/settings',{method:'PUT',body:b});await reload();toast('Pricing and settings saved');return}
